ext('c12_eng_ch14',[
C("🍁","कविता और कवि की दुनिया",["कवि: डब्ल्यू. एच. ऑडेन","बीसवीं सदी के अंग्रेज़ी कवि","दो विश्वयुद्धों के बीच का समय","सामाजिक चिंता की कविता"],"इस कविता के कवि डब्ल्यू एच ऑडेन बीसवीं सदी के प्रमुख अंग्रेज़ी कवि हैं। उनका समय दो विश्वयुद्धों के बीच का था, जब यूरोप में बेरोज़गारी, डर और राजनीतिक तनाव फैला हुआ था। उनकी कविताओं में समाज की चिंता और आम आदमी की बेचैनी साफ़ झलकती है। इस कविता में पतझड़ केवल मौसम नहीं है, बल्कि उस दौर की गिरावट, उदासी और अनिश्चितता का प्रतीक है।"),
Q("कविता में पतझड़ किसका प्रतीक है?","गिरावट, पतन, अनिश्चितता और समय के बीतने का","प्रतीक सोचिए... पतझड़ में पत्ते गिरते हैं, चीज़ें पुरानी होकर ख़त्म होती हैं। कवि इसे समाज और जीवन के पतन तथा आने वाले अनजाने ख़तरे के संकेत के रूप में लेता है। इसलिए पतझड़ गिरावट और अनिश्चितता का प्रतीक है।"),
C("🍃","पत्तों का गिरना: चित्र और भाव",["पत्ते तेज़ी से गिरते","पक्षी चले गए","पेड़ नंगे","ख़ालीपन और सन्नाटा"],"कविता में पत्तों का तेज़ी से गिरना एक सजीव चित्र है। पत्ते गिरते जाते हैं, पक्षी भी चले जाते हैं और पेड़ ख़ाली रह जाते हैं। यह दृश्य उदासी और सन्नाटे का भाव जगाता है। जैसे कोई चीज़ हाथ से छूटती जा रही हो और हम उसे रोक न पा रहे हों। कवि इस प्राकृतिक दृश्य के सहारे दिखाते हैं कि समय किसी के रोके नहीं रुकता और परिवर्तन अवश्यंभावी है।"),
Q("पत्तों के तेज़ी से गिरने से कवि क्या दिखाना चाहता है?","समय का तेज़ी से बीतना और आसन्न बदलाव या संकट","सोचिए... पत्तों का तेज़ी से गिरना बताता है कि सब कुछ जल्दी-जल्दी बदल रहा है। इससे एक डर और बेचैनी पैदा होती है कि आगे कुछ अच्छा नहीं होने वाला। यह समय की गति और आने वाले संकट का संकेत है।"),
C("😟","कविता का स्वर",["उदास और चिंतित","चेतावनी का स्वर","अनिश्चित भविष्य","फिर भी सच्चाई का सामना"],"कविता का स्वर गंभीर, उदास और चिंताजनक है। कवि जैसे पाठक को आने वाली मुश्किल की चेतावनी दे रहा है। अनिश्चित भविष्य का डर हर पंक्ति में महसूस होता है। पर कवि निराशा में डूबा नहीं है। वह सच्चाई को सीधे और बिना सजावट के कहता है। यह सीधा कहना ही कविता को ताक़त देता है और पाठक को सोचने पर मजबूर करता है।"),
Q("कविता के स्वर को एक शब्द में क्या कहेंगे?","गंभीर और चिंताजनक (उदास)","स्वर के लिए एक शब्द सोचिए... कविता में उदासी और चिंता दोनों हैं, इसलिए स्वर गंभीर और चिंताजनक है। कवि निराशा नहीं दिखाता, पर आने वाले ख़तरे को लेकर सावधान करता है।"),
C("🎨","भाषा और बिंब",["सरल शब्द","प्रकृति के बिंब","मानवीय चिंता से जुड़ाव","लयबद्ध पंक्तियाँ"],"ऑडेन ने सरल भाषा चुनी है, पर उसका प्रभाव गहरा है। प्रकृति के बिंब, जैसे गिरते पत्ते, नंगी डालियाँ और उड़ते पक्षी, सीधे मन पर असर डालते हैं। इन बिंबों को मानवीय चिंता से जोड़कर कवि कविता को अर्थ का दूसरा स्तर देते हैं। कविता की पंक्तियों में एक लय है जो पाठक को आगे बहाकर ले जाती है, लेकिन भाव भारी रहते हैं।"),
Q("कविता में प्रकृति के बिंब का क्या उपयोग है?","मानवीय और सामाजिक चिंता को प्रतीकात्मक रूप में दिखाना","सोचिए... कवि सीधे राजनीति की बात नहीं करता, बल्कि पतझड़ के दृश्य से अपनी बात कहता है। इससे बात ज़्यादा सुंदर और असरदार बन जाती है। प्रकृति का दृश्य मानवीय चिंता का रूपक बन जाता है।"),
C("🌱","आशा की संभावना",["पतझड़ के बाद वसंत","हर अंत में नई शुरुआत","जागरूक होना ज़रूरी","सहयोग और साहस"],"यह कविता उदास है, पर प्रकृति का नियम हमें एक और बात सिखाता है। पतझड़ के बाद वसंत ज़रूर आता है। यानी हर पतन के बाद नई शुरुआत की संभावना रहती है। पर इसके लिए हमें जागरूक रहना और साथ मिलकर साहस से कदम उठाना ज़रूरी है। कविता हमें सावधान करती है ताकि हम समय रहते ज़रूरी बदलाव कर सकें।"),
Q("पतझड़ के बाद कौन-सी ऋतु आती है और वह क्या दर्शाती है?","वसंत; नई शुरुआत और आशा को","सोचिए... प्रकृति में चक्र चलता है। पतझड़ के बाद सर्दी और फिर वसंत आता है, जो नई कोंपलों और आशा का समय है। इसलिए कठिन समय के बाद अच्छे समय की उम्मीद रखनी चाहिए।"),
C("✍️","उत्तर और भावार्थ के सुझाव",["प्रतीक स्पष्ट लिखें","स्वर का उल्लेख","एक बिंब का उदाहरण","निष्कर्ष में आशा"],"भावार्थ लिखते समय पतझड़ के प्रतीक का अर्थ साफ़ लिखिए, यानी गिरावट और अनिश्चितता। फिर कविता का स्वर बताइए और एक बिंब का उदाहरण दीजिए। अंत में निष्कर्ष में यह लिखिए कि कवि चेतावनी देता है और प्रकृति के चक्र की तरह आशा भी याद दिलाता है। कविता के शब्द वैसे के वैसे उतारने के बजाय अपने शब्दों में अर्थ लिखिए। इससे उत्तर मौलिक और असरदार बनता है।"),
],7)
